import { NextRequest, NextResponse } from "next/server";
import { SESSION_COOKIE } from "@/lib/session-cookie";

// Cheap gate: cookie presence only. Real session validation happens
// server-side in the admin layout (Redis lookup needs Node runtime).
export function middleware(req: NextRequest) {
  if (!req.cookies.get(SESSION_COOKIE)) {
    const url = req.nextUrl.clone();
    url.pathname = "/login";
    return NextResponse.redirect(url);
  }
  return NextResponse.next();
}

export const config = { matcher: ["/admin/:path*"] };
import "server-only";
import { randomBytes } from "node:crypto";
import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import { redis } from "./redis";
import { SESSION_COOKIE } from "./session-cookie";

export { SESSION_COOKIE };
const SESSION_TTL_SEC = 7 * 24 * 3600;

export type Session = {
  userId: string;
  businessId: string;
  role: "owner" | "staff";
  name: string;
  email: string;
};

const key = (token: string) => `sess:${token}`;

// Sessions live in Redis: opaque 256-bit token in an httpOnly cookie,
// all session data server-side, TTL-refreshed on each read.
export async function createSession(data: Session): Promise<void> {
  const token = randomBytes(32).toString("hex");
  await redis().set(key(token), JSON.stringify(data), "EX", SESSION_TTL_SEC);
  (await cookies()).set(SESSION_COOKIE, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    maxAge: SESSION_TTL_SEC,
    path: "/",
  });
}

export async function getSession(): Promise<Session | null> {
  const token = (await cookies()).get(SESSION_COOKIE)?.value;
  if (!token) return null;
  const raw = await redis().get(key(token));
  if (!raw) return null;
  await redis().expire(key(token), SESSION_TTL_SEC); // sliding expiration
  return JSON.parse(raw) as Session;
}

export async function requireSession(): Promise<Session> {
  const session = await getSession();
  if (!session) redirect("/login");
  return session;
}

export async function destroySession(): Promise<void> {
  const store = await cookies();
  const token = store.get(SESSION_COOKIE)?.value;
  if (token) await redis().del(key(token));
  store.delete(SESSION_COOKIE);
}
// Importable from edge middleware (no server-only deps).
export const SESSION_COOKIE = "kezek_session";
import Link from "next/link";
import { requireSession } from "@/lib/session";
import { logout } from "@/app/login/actions";

const nav = [
  ["/admin", "Calendar"],
  ["/admin/clients", "Clients"],
  ["/admin/services", "Services"],
  ["/admin/staff", "Staff"],
  ["/admin/reports", "Reports"],
  ["/admin/analytics", "Analytics"],
  ["/admin/notifications", "Notifications"],
  ["/admin/audit", "Audit"],
] as const;

export default async function AdminLayout({ children }: { children: React.ReactNode }) {
  const session = await requireSession();
  return (
    <div className="min-h-screen bg-zinc-50">
      <header className="border-b border-zinc-200 bg-white">
        <div className="mx-auto flex max-w-6xl items-center justify-between gap-4 px-4 py-3">
          <div className="flex items-center gap-6 overflow-x-auto">
            <span className="text-lg font-bold">kezek</span>
            <nav className="flex gap-4 text-sm">
              {nav.map(([href, label]) => (
                <Link key={href} href={href} className="whitespace-nowrap text-zinc-600 hover:text-zinc-900">
                  {label}
                </Link>
              ))}
            </nav>
          </div>
          <form action={logout} className="flex items-center gap-3 text-sm">
            <span className="hidden text-zinc-500 sm:inline">{session.name}</span>
            <button className="rounded-lg border border-zinc-300 px-3 py-1 hover:bg-zinc-100">Sign out</button>
          </form>
        </div>
      </header>
      <main className="mx-auto max-w-6xl p-4">{children}</main>
    </div>
  );
}
"use server";
import { and, eq } from "drizzle-orm";
import { revalidatePath } from "next/cache";
import { db, schema as s } from "@/db";
import { setBookingStatus } from "@/lib/booking";
import { requireSession } from "@/lib/session";

export async function updateBookingStatus(formData: FormData): Promise<void> {
  const session = await requireSession();
  const bookingId = String(formData.get("bookingId"));
  const status = String(formData.get("status")) as "completed" | "cancelled" | "no_show";
  if (!["completed", "cancelled", "no_show"].includes(status)) return;
  await setBookingStatus({
    businessId: session.businessId,
    bookingId,
    status,
    actorUserId: session.userId,
  });
  revalidatePath("/admin");
}

export async function saveService(formData: FormData): Promise<void> {
  const session = await requireSession();
  const id = formData.get("id") ? String(formData.get("id")) : null;
  const values = {
    name: String(formData.get("name") ?? "").trim(),
    durationMin: Number(formData.get("durationMin")),
    priceKzt: Number(formData.get("priceKzt")),
  };
  if (!values.name || !Number.isFinite(values.durationMin) || !Number.isFinite(values.priceKzt)) return;

  if (id) {
    await db
      .update(s.services)
      .set(values)
      .where(and(eq(s.services.id, id), eq(s.services.businessId, session.businessId)));
  } else {
    await db.insert(s.services).values({ ...values, businessId: session.businessId });
  }
  await db.insert(s.auditLog).values({
    businessId: session.businessId,
    actorUserId: session.userId,
    action: id ? "service.update" : "service.create",
    entity: "service",
    entityId: id,
    meta: values,
  });
  revalidatePath("/admin/services");
}

export async function toggleService(formData: FormData): Promise<void> {
  const session = await requireSession();
  const id = String(formData.get("id"));
  const [svc] = await db
    .select()
    .from(s.services)
    .where(and(eq(s.services.id, id), eq(s.services.businessId, session.businessId)));
  if (!svc) return;
  await db.update(s.services).set({ isActive: !svc.isActive }).where(eq(s.services.id, id));
  revalidatePath("/admin/services");
}

export async function saveStaff(formData: FormData): Promise<void> {
  const session = await requireSession();
  const name = String(formData.get("name") ?? "").trim();
  if (!name) return;
  await db.insert(s.staff).values({ businessId: session.businessId, name });
  await db.insert(s.auditLog).values({
    businessId: session.businessId,
    actorUserId: session.userId,
    action: "staff.create",
    entity: "staff",
    meta: { name },
  });
  revalidatePath("/admin/staff");
}

export async function toggleStaff(formData: FormData): Promise<void> {
  const session = await requireSession();
  const id = String(formData.get("id"));
  const [row] = await db
    .select()
    .from(s.staff)
    .where(and(eq(s.staff.id, id), eq(s.staff.businessId, session.businessId)));
  if (!row) return;
  await db.update(s.staff).set({ isActive: !row.isActive }).where(eq(s.staff.id, id));
  revalidatePath("/admin/staff");
}

export async function toggleStaffService(formData: FormData): Promise<void> {
  const session = await requireSession();
  const staffId = String(formData.get("staffId"));
  const serviceId = String(formData.get("serviceId"));
  // both must belong to this business
  const [st] = await db
    .select()
    .from(s.staff)
    .where(and(eq(s.staff.id, staffId), eq(s.staff.businessId, session.businessId)));
  const [svc] = await db
    .select()
    .from(s.services)
    .where(and(eq(s.services.id, serviceId), eq(s.services.businessId, session.businessId)));
  if (!st || !svc) return;
  const [link] = await db
    .select()
    .from(s.staffServices)
    .where(and(eq(s.staffServices.staffId, staffId), eq(s.staffServices.serviceId, serviceId)));
  if (link) {
    await db
      .delete(s.staffServices)
      .where(and(eq(s.staffServices.staffId, staffId), eq(s.staffServices.serviceId, serviceId)));
  } else {
    await db.insert(s.staffServices).values({ staffId, serviceId });
  }
  revalidatePath("/admin/staff");
}

