export default async function AuditPage() {
  const session = await requireSession();
  const rows = await db
    .select({
      id: s.auditLog.id,
      action: s.auditLog.action,
      entity: s.auditLog.entity,
      meta: s.auditLog.meta,
      createdAt: s.auditLog.createdAt,
      actor: s.users.name,
