import { calendarChannel } from "@/lib/booking";
import { redis } from "@/lib/redis";
import { getSession } from "@/lib/session";

export const dynamic = "force-dynamic";

// SSE stream of calendar changes for the admin UI.
// Each connection gets its own Redis subscriber (a subscribing connection
// can't run other commands); closed on client disconnect.
export async function GET() {
  const session = await getSession();
  if (!session) return new Response("unauthorized", { status: 401 });

  const sub = redis().duplicate();
  await sub.subscribe(calendarChannel(session.businessId));
  const encoder = new TextEncoder();
  let heartbeat: ReturnType<typeof setInterval>;

  const stream = new ReadableStream({
    start(controller) {
      controller.enqueue(encoder.encode(`event: hello\ndata: {}\n\n`));
      sub.on("message", (_channel, message) => {
        controller.enqueue(encoder.encode(`data: ${message}\n\n`));
      });
      heartbeat = setInterval(() => {
        controller.enqueue(encoder.encode(`: ping\n\n`));
      }, 25_000);
    },
    cancel() {
      clearInterval(heartbeat);
      void sub.quit();
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
    },
  });
}
"use server";
import bcrypt from "bcryptjs";
import { eq } from "drizzle-orm";
import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { db, schema } from "@/db";
import { rateLimit } from "@/lib/ratelimit";
import { createSession, destroySession } from "@/lib/session";

export async function login(
  _prev: { error: string } | null,
  formData: FormData,
): Promise<{ error: string } | null> {
  const email = String(formData.get("email") ?? "").trim().toLowerCase();
  const password = String(formData.get("password") ?? "");
  if (!email || !password) return { error: "Enter an email and a password" };

  const ip = (await headers()).get("x-forwarded-for")?.split(",")[0] ?? "local";
  if (!(await rateLimit(`login:${ip}`, 10, 60))) {
    return { error: "Too many attempts, wait a minute" };
  }

  const user = await db.query.users.findFirst({ where: eq(schema.users.email, email) });
  if (!user || !(await bcrypt.compare(password, user.passwordHash))) {
    return { error: "Wrong email or password" };
  }
  if (!user.businessId) return { error: "This user is not attached to a business" };

  await createSession({
    userId: user.id,
    businessId: user.businessId,
    role: user.role,
    name: user.name,
    email: user.email,
  });
  redirect("/admin");
}

export async function logout(): Promise<void> {
  await destroySession();
  redirect("/login");
}
