export async function seedBusiness(opts?: { slug?: string; timezone?: string }) {
  const [business] = await db
    .insert(s.businesses)
    .values({
      slug: opts?.slug ?? "testsalon",
      name: "Test Salon",
      timezone: opts?.timezone ?? "Asia/Almaty",
      holdTtlSec: 300,
    })
    .returning();

  await db.insert(s.businessHours).values(
