      closeTime: "20:00",
    })),
  );

  const [owner] = await db
    .insert(s.users)
    .values({
      email: `owner@${business.slug}.test`,
      passwordHash: await bcrypt.hash("test-password", 4), // low cost: tests, not production
      name: "Owner",
      role: "owner",
      businessId: business.id,
