const statusStyle: Record<string, string> = {
  pending: "bg-amber-100 text-amber-800",
  processing: "bg-sky-100 text-sky-800",
  sent: "bg-emerald-100 text-emerald-800",
  dead: "bg-red-100 text-red-800",
  cancelled: "bg-zinc-200 text-zinc-600",
};

export default async function NotificationsPage() {
  const session = await requireSession();

  const queue = await db
    .select()
    .from(s.outbox)
    .where(eq(s.outbox.businessId, session.businessId))
    .orderBy(desc(s.outbox.createdAt))
    .limit(50);

  const delivered = await db
    .select()
    .from(s.messageLog)
    .where(eq(s.messageLog.businessId, session.businessId))
    .orderBy(desc(s.messageLog.createdAt))
    .limit(50);

  const fmt = new Intl.DateTimeFormat("en-GB", { dateStyle: "short", timeStyle: "short" });
  const counts = queue.reduce<Record<string, number>>((acc, r) => {
    acc[r.status] = (acc[r.status] ?? 0) + 1;
    return acc;
  }, {});

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-xl font-semibold">Notifications</h1>
        <p className="mt-1 text-sm text-zinc-500">
          Messages are queued inside the same transaction as the booking itself and delivered by a separate
          worker (<code className="rounded bg-zinc-100 px-1">pnpm worker</code>).
        </p>
      </div>

